def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    me_def = sum(1 for a in me if a == 'D')
    opp_def = sum(1 for a in opp if a == 'D')
    last_me, last_opp = history[-1]

    if n == 99:
        return 'D'

    retaliation = 0
    for i in range(1, n):
        if me[i-1] == 'D' and opp[i] == 'D':
            retaliation += 1

    if opp_def == 0:
        if n == 2:
            return 'D'
        if last_me == 'D':
            return 'C'
        if me_def < n // 10:
            return 'D'
        return 'C'

    if retaliation > 0:
        if last_opp == 'D' and last_me == 'C':
            return 'D' if opp_def > n * 0.5 else 'C'
        return 'C'

    if opp_def <= max(1, n // 10):
        if last_opp == 'D':
            return 'C'
        if last_me == 'D':
            return 'C'
        if me_def < n // 10:
            return 'D'
        return 'C'

    if last_opp == 'D' and last_me == 'D':
        if opp_def <= n // 2:
            return 'C'
        return 'D'

    if last_opp == 'D' and last_me == 'C':
        return 'D'

    if last_opp == 'C':
        if n >= 3:
            recent_me = me[-3:]
            recent_opp = opp[-3:]
            if all(a == 'D' for a in recent_me) and all(a == 'C' for a in recent_opp):
                return 'D'
        if last_me == 'D':
            return 'C'
        if me_def < n // 10:
            return 'D'
        return 'C'

    return 'C'
